POLICY = "Retry only idempotent effects, bounded with exponential backoff and jitter. Never blindly repeat a payment charge."
COST = {"rule": 0, "review": 5}  # illustrative future review cost, not measured here
review_queue = []

def apply_rule(case):
    if case["idempotent"] is True:
        return "bounded retry with backoff and jitter"
    return "do not automatically retry"

def send_to_review(case):
    review_queue.append(case["name"])
    return "queued for council/human review"

HANDLERS = {"rule": apply_rule, "review": send_to_review}
print(apply_rule(cases[2]))  # even a misroute must not repeat the non-idempotent payment

EXAMPLES = ("Transient idempotent lookup, latency budget available -> rule. "
            "Unknown effect idempotency -> review. Uncertain non-idempotent charge -> review. "
            "Optional service needs fallback judgement -> review.")

def route(case):
    prompt = (f"Policy: {POLICY}\n{EXAMPLES}\nCase: {json.dumps(case)}\n"
              'Reply with JSON only: {"route": "rule" or "review", "reason": "one sentence"}')
    try:
        reply = json.loads(ask(prompt))
    except json.JSONDecodeError:
        return "review", "not JSON"
    if not isinstance(reply, dict) or reply.get("route") not in HANDLERS:
        return "review", "unknown or malformed route"
    return reply["route"], reply.get("reason", "")
